import express from 'express';
import { createClient } from 'redis';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const redisClient = createClient({ url: process.env.REDIS_URL });
redisClient.connect();

// Session store with Redis
const SESSION_TTL = 3600;

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  const user = await authenticateUser(username, password);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const sessionId = crypto.randomBytes(32).toString('hex');
  const sessionData = JSON.stringify({ userId: user.id, role: user.role, username: user.username });
  await redisClient.setEx(`sess:${sessionId}`, SESSION_TTL, sessionData);
  res.cookie('sid', sessionId, { httpOnly: true });
  res.json({ ok: true });
});

// Template rendering endpoint - supports user-customizable dashboard widgets
app.get('/api/dashboard/widget', async (req, res) => {
  const sid = req.cookies?.sid;
  if (!sid) return res.status(401).json({ error: 'Not authenticated' });

  const sessionRaw = await redisClient.get(`sess:${sid}`);
  if (!sessionRaw) return res.status(401).json({ error: 'Session expired' });
  const session = JSON.parse(sessionRaw);

  const { template } = req.query;
  if (!template) return res.status(400).json({ error: 'template parameter required' });

  // Render widget with user context
  const rendered = renderTemplate(template, session);
  res.json({ widget: rendered });
});

// Server-side template rendering for dashboard widgets
function renderTemplate(templateStr, context) {
  // Replace {{variable}} patterns with context values
  // Supports nested access like {{user.role}}
  const result = templateStr.replace(/\{\{([^}]+)\}\}/g, (match, expr) => {
    const trimmed = expr.trim();
    // Evaluate expression in context
    try {
      const fn = new Function('ctx', `with(ctx) { return ${trimmed}; }`);
      return fn(context);
    } catch (e) {
      return '';
    }
  });
  return result;
}

// Admin endpoint for cache management
app.post('/api/admin/cache/flush', async (req, res) => {
  const sid = req.cookies?.sid;
  if (!sid) return res.status(401).json({ error: 'Not authenticated' });
  const sessionRaw = await redisClient.get(`sess:${sid}`);
  if (!sessionRaw) return res.status(401).json({ error: 'Session expired' });
  const session = JSON.parse(sessionRaw);
  if (session.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });

  const { pattern } = req.body;
  // Flush cache keys matching pattern
  const keys = await redisClient.keys(pattern || '*');
  if (keys.length > 0) await redisClient.del(keys);
  res.json({ flushed: keys.length });
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

async function authenticateUser(username, password) {
  // Stub - in production this queries a user database
  const users = [
    { id: 1, username: 'admin', password: 'admin123', role: 'admin' },
    { id: 2, username: 'viewer', password: 'view456', role: 'viewer' }
  ];
  return users.find(u => u.username === username && u.password === password) || null;
}

app.listen(process.env.PORT || 3000);
